from database import connect

class Ledger:
    def __init__(self, path):
        self.db = connect(path)

    def record(self, events):
        for e in events:
            self.db.execute(
                "INSERT OR IGNORE INTO events (id, account, amount, status) VALUES (?, ?, ?, ?)",
                (e['id'], e['account'], e['amount'], e['status'])
            )
        self.db.commit()

    def totals(self):
        cursor = self.db.execute(
            "SELECT account, SUM(amount) FROM events WHERE status = 'posted' GROUP BY account"
        )
        return {row[0]: row[1] for row in cursor.fetchall()}

    def close(self):
        self.db.close()

from repository import Ledger

def apply(path, events):
    # Validation
    for e in events:
        if not isinstance(e.get('id'), str) or not e.get('id'):
            raise ValueError("Invalid id")
        if not isinstance(e.get('account'), str) or not e.get('account'):
            raise ValueError("Invalid account")
        amount = e.get('amount')
        if not isinstance(amount, int) or isinstance(amount, bool):
            raise ValueError("Invalid amount")
        if e.get('status') not in ('posted', 'pending'):
            raise ValueError("Invalid status")

    ledger = Ledger(path)
    try:
        ledger.record(events)
        return ledger.totals()
    finally:
        ledger.close()

