export function available(input: { stock: Record<string, number>, reservations: { sku: string, quantity: number, expires: number }[], now: number }): Record<string, number> {
  const { stock, reservations, now } = input;
  const result: Record<string, number> = {};
  for (const sku in stock) {
    result[sku] = stock[sku];
  }
  for (const res of reservations) {
    if (res.expires > now && stock.hasOwnProperty(res.sku)) {
      result[res.sku] -= res.quantity;
    }
  }
  for (const sku in result) {
    if (result[sku] < 0) {
      result[sku] = 0;
    }
  }
  return result;
}

