			input: `[{"stock": {"a": 10}, "reservations": [{"sku": "a", "quantity": 5, "expires": 5}], "now": 10}]`,
			expected: `[{"a": 10}]`,
		},
		{
			name: "Unknown SKU in reservation",
			input: `[{"stock": {"a": 10}, "reservations": [{"sku": "b", "quantity": 5, "expires": 15}], "now": 10}]`,
			expected: `[{"a": 10}]`,
		},
		{
