			input: `[{"stock": {"a": 10}, "reservations": [{"sku": "a", "quantity": 2, "expires": 15}, {"sku": "a", "quantity": 3, "expires": 20}], "now": 10}]`,
			expected: `[{"a": 5}]`,
		},
		{
			name: "Stock is zero",
			input: `[{"stock": {"a": 0}, "reservations": [{"sku": "a", "quantity": 5, "expires": 15}], "now": 10}]`,
			expected: `[{"a": 0}]`,
		},
		{
			name: "Empty inputs",
			input: `[{"stock": {}, "reservations": [], "now": 10}]`,
			expected: `[{}]`,
		},
	}

