func solve(x map[string]any) any {
	stock := x["stock"].(map[string]any)
	reservations := x["reservations"].([]any)
	now := x["now"].(float64)

	out := make(map[string]float64)
	for k, v := range stock {
		out[k] = v.(float64)
	}

	for _, raw := range reservations {
		r := raw.(map[string]any)
		sku := r["sku"].(string)
		quantity := r["quantity"].(float64)
		expires := r["expires"].(float64)

		if expires > now {
			if _, ok := out[sku]; ok {
				out[sku] -= quantity
			}
		}
	}

	for k, v := range out {
		if v < 0 {
			out[k] = 0
		}
	}

	return out
}

